WARMUPS = [{'name': 'Lip Trill', 'duration': 30, 'icon': '👄', 'desc': 'Blow air through loosely closed lips to create a trill. Do this for 30 seconds. Feel your lips vibrate - this warms up your vocal cords without strain.', 'benefit': 'Warms vocal cords, reduces tension'}, {'name': 'Humming Scale', 'duration': 30, 'icon': '🎵', 'desc': 'Hum up and down a comfortable scale 3 times. Keep your jaw relaxed and your lips lightly closed. Feel the vibration in your chest and face.', 'benefit': 'Extends vocal range, builds resonance'}, {'name': 'Jaw Release', 'duration': 20, 'icon': '🦷', 'desc': 'Open your mouth as wide as comfortable, hold 3 seconds, close slowly. Repeat 5 times. This releases tension that narrows your voice.', 'benefit': 'Releases jaw tension, opens resonance'}, {'name': 'Tongue Stretch', 'duration': 20, 'icon': '👅', 'desc': 'Stick tongue out as far as it goes, hold 3 sec, pull back. Move it side to side 5 times. This fights mumbling and unclear consonants.', 'benefit': 'Sharpens articulation and clarity'}, {'name': 'Breath Control', 'duration': 60, 'icon': '💨', 'desc': 'Breathe in for 4 counts, hold 4, exhale slowly for 8. Repeat 5 times. Controlled breathing is the foundation of confident speech. No rushing.', 'benefit': 'Builds breath support and calm under pressure'}, {'name': 'Resonance Buzz', 'duration': 30, 'icon': '🐝', 'desc': 'Say mmmmm-BAH, mmmmm-BAY, mmmmm-BEE slowly and clearly. Feel where the sound vibrates. Move it from your nose to your chest.', 'benefit': 'Builds rich vocal resonance'}, {'name': 'Pace Drill', 'duration': 45, 'icon': '⏱', 'desc': 'Say this at 3 speeds - slow, normal, fast: The quick brown fox jumps over the lazy dog. Notice how meaning and clarity change with pace.', 'benefit': 'Pace awareness and control'}, {'name': 'Pause Practice', 'duration': 30, 'icon': '⏸', 'desc': 'Say a sentence, then deliberately pause for 2 full seconds before the next. Repeat 3 times with different sentences. Silence is power.', 'benefit': 'Replaces fillers with confident silence'}, {'name': 'Power Stance', 'duration': 30, 'icon': '🧍', 'desc': 'Stand tall, feet shoulder-width, hands at sides. Take 3 deep breaths and say I am ready to speak with clarity and confidence three times.', 'benefit': 'Mental and physical confidence reset'}, {'name': 'Articulation Drill', 'duration': 45, 'icon': '💬', 'desc': 'Repeat 5 times clearly: puh-tuh-kuh, puh-tuh-kuh, puh-tuh-kuh. Then: wuh-ruh-luh. These activate your lips, tongue, and soft palate together.', 'benefit': 'Sharpens all consonants and articulation'}]

