DAYS = [{'day': 1, 'phase': 1, 'title': 'The Anchor', 'focus': 'Kill the panic reflex', 'drill': 'Pause 3 seconds before every sentence. Breathe out. Feel your feet. Then speak.', 'tip': 'Silence before you start signals confidence. Rushing signals fear.', 'format': 'Opinion'}, {'day': 2, 'phase': 1, 'title': 'Slow Down', 'focus': 'Override the rushing reflex', 'drill': 'Speak at half your normal speed. Every sentence minimum 3 seconds. Uncomfortable = correct.', 'tip': 'Nervous people rush. Leaders pause. Slow IS confident.', 'format': 'Opinion'}, {'day': 3, 'phase': 1, 'title': 'One Point Only', 'focus': 'Stop over-explaining', 'drill': 'State one point. One reason. One example. Stop. Do not add a fourth sentence.', 'tip': 'Over-explaining buries your point. Trust your listener.', 'format': 'Problem Solution'}, {'day': 4, 'phase': 1, 'title': 'Voice Breath', 'focus': 'Build vocal presence', 'drill': 'Deep breath into your belly before speaking. Speak on the exhale. Record and notice the difference.', 'tip': 'Shallow breathing = thin voice. Belly breath = authority.', 'format': 'Motivation Speech'}, {'day': 5, 'phase': 1, 'title': 'Downward Inflection', 'focus': 'Sound decisive not uncertain', 'drill': 'End every sentence with your voice going DOWN. Record yourself. Fix every upward tail.', 'tip': 'Rising at end of statements sounds like asking permission. Drop it.', 'format': 'Opinion'}, {'day': 6, 'phase': 1, 'title': 'Filler Detox', 'focus': 'Eliminate um, uh, so, like', 'drill': 'Speak for 90 seconds. Every time you want a filler - use SILENCE instead. Count fillers after.', 'tip': 'Silence is 10x more powerful than any filler word.', 'format': 'Teach It'}, {'day': 7, 'phase': 1, 'title': 'Week 1 Recap', 'focus': 'Consolidate your foundations', 'drill': 'Combine all 5 skills: anchor pause, slow pace, one point, belly breath, downward inflection.', 'tip': 'You have now rewired 5 reflexes. Notice which one is still hardest.', 'format': 'Positive Reflection'}, {'day': 8, 'phase': 1, 'title': 'The Power Pause', 'focus': 'Use silence as punctuation', 'drill': 'After every key point - pause 2 full seconds. Do not fill it. Let it land.', 'tip': 'The pause after your point is where your listener processes it. Do not steal it.', 'format': 'Persuasion'}, {'day': 9, 'phase': 1, 'title': 'Strong Opener', 'focus': 'Start with impact not warmup', 'drill': 'Begin with your strongest sentence. No thanks, no um, no so today I want to talk about. Hit them immediately.', 'tip': 'You have 8 seconds. Use them.', 'format': 'What If'}, {'day': 10, 'phase': 1, 'title': 'Strong Closer', 'focus': 'Land the ending with authority', 'drill': 'End with a clear final statement. No trailing off. No and yeah so that is it. Land it. Stop.', 'tip': 'People remember your first and last line. Make the last one count.', 'format': 'STAR Method'}, {'day': 11, 'phase': 1, 'title': 'Vocabulary Steal', 'focus': 'Use one new powerful word', 'drill': 'Pick one word from your reading today. Use it naturally in your speech. Own it.', 'tip': 'You build vocabulary by using stolen words within 24 hours of finding them.', 'format': 'Compare and Contrast'}, {'day': 12, 'phase': 1, 'title': 'Eye Contact Drill', 'focus': 'Command presence not just words', 'drill': 'Look directly at your camera the entire time. No looking away. No looking at notes.', 'tip': 'Looking away signals doubt. The camera is your audience. Hold it.', 'format': 'Teach It'}, {'day': 13, 'phase': 1, 'title': 'The Rerecord', 'focus': 'Own your own feedback', 'drill': 'Record once freely. Listen back. Find your 2 weakest moments. Rerecord those sentences only. Notice the gap.', 'tip': 'The gap between your first and second take is your growth rate.', 'format': 'Opinion'}, {'day': 14, 'phase': 1, 'title': 'Phase 1 Graduation', 'focus': 'Full foundation run - all skills active', 'drill': '60-90 seconds. Every skill from Days 1-13 active simultaneously. This is your Phase 1 benchmark.', 'tip': 'You are not the same speaker you were on Day 1. Notice that.', 'format': 'Storytelling'}, {'day': 15, 'phase': 2, 'title': 'Tension Opening', 'focus': 'Hook your listener in sentence one', 'drill': 'Open with a problem, a risk, or a provocative statement. No context-setting first. Start with tension.', 'tip': 'Influential speakers do not warm up. They ignite.', 'format': 'What If'}, {'day': 16, 'phase': 2, 'title': 'The Insight Punch', 'focus': 'Say what others miss', 'drill': 'After stating the problem - say: what most people miss about this is... Then finish it with something real.', 'tip': 'Insight is what separates a speaker from a commentator.', 'format': 'Devil Advocate'}, {'day': 17, 'phase': 2, 'title': 'The Action Close', 'focus': 'End with a clear call to action', 'drill': 'End every speech with exactly one action: Here is what we do next. One sentence. Specific. Decisive.', 'tip': 'Inspiration without direction is entertainment. Add the action.', 'format': 'Problem Solution'}, {'day': 18, 'phase': 2, 'title': 'Full Influence Formula', 'focus': 'Tension plus Insight plus Action in one speech', 'drill': 'Use all three: open with tension, deliver the insight, close with action. This is the influence formula.', 'tip': 'Every influential speech in history follows this shape.', 'format': 'Persuasion'}, {'day': 19, 'phase': 2, 'title': 'Specificity Drill', 'focus': 'Kill vague language', 'drill': 'Replace every vague word: some, many, kind of, a bit, quite. Replace with a number, a name, or a specific fact.', 'tip': 'Vague language sounds uncertain. Specific language sounds expert.', 'format': 'Two Minute Briefing'}, {'day': 20, 'phase': 2, 'title': 'Emotional Anchor', 'focus': 'Make them feel something', 'drill': 'In your speech include one moment where you connect emotionally. A real story, a real consequence, a real person.', 'tip': 'Logic makes people think. Emotion makes people act.', 'format': 'Storytelling'}, {'day': 21, 'phase': 2, 'title': 'The Contrast', 'focus': 'Use comparison to create impact', 'drill': 'Build your key point as a contrast: not X but Y. Not what we are doing but what we should be doing.', 'tip': 'Contrast is the fastest way to make a point memorable.', 'format': 'Compare and Contrast'}, {'day': 22, 'phase': 2, 'title': 'The Rule of Three', 'focus': 'Make your points stick', 'drill': 'Structure everything in threes. Three reasons. Three steps. Three consequences. Always three.', 'tip': 'The human brain organises in threes. Work with it.', 'format': 'Opinion'}, {'day': 23, 'phase': 2, 'title': 'Conviction Drill', 'focus': 'Mean every word you say', 'drill': 'Before recording ask yourself: do I actually believe this? If not pick a different topic. Conviction is not performed. It is felt.', 'tip': 'People do not follow what you say. They follow what you mean.', 'format': 'Motivation Speech'}, {'day': 24, 'phase': 2, 'title': 'Brevity Drill', 'focus': 'Say it in half the words', 'drill': 'Record 90 seconds. Then rerecord and say the same thing in 45 seconds. Cut every word that does not carry weight.', 'tip': 'Brevity is not simplicity. It is discipline.', 'format': 'Two Minute Briefing'}, {'day': 25, 'phase': 2, 'title': 'Phase 2 Benchmark', 'focus': 'Authority and influence combined', 'drill': 'Full speech - Tension opener, Insight, Action close, Rule of Three, specific language, emotional moment.', 'tip': 'You are now building a speaker identity. Notice your natural strengths.', 'format': 'Persuasion'}, {'day': 26, 'phase': 3, 'title': 'Your Speaker Identity', 'focus': 'Find your natural style and own it', 'drill': 'Record freely - no rules today. Just speak. Listen back. What sounds most like YOU at your best?', 'tip': 'The goal is not to sound like someone else. It is to sound like your best self.', 'format': 'Positive Reflection'}, {'day': 27, 'phase': 3, 'title': 'High Stakes Simulation', 'focus': 'Perform under pressure', 'drill': 'Imagine you are presenting to your senior leadership right now. Same stakes. Same energy. Go.', 'tip': 'You do not rise to the level of the room. You fall to the level of your preparation.', 'format': 'Two Minute Briefing'}, {'day': 28, 'phase': 3, 'title': 'The Difficult Topic', 'focus': 'Hold authority when challenged', 'drill': 'Pick the topic you find most uncomfortable or controversial. Speak on it with full conviction and structure.', 'tip': 'Influential speakers do not only speak when it is safe.', 'format': 'Devil Advocate'}, {'day': 29, 'phase': 3, 'title': 'The Signature Speech', 'focus': 'Deliver something you are proud of', 'drill': 'Pick your strongest format. Your best topic. Bring everything you have learned. Make this one count.', 'tip': 'This is the speech that shows you who you have become.', 'format': 'Storytelling'}, {'day': 30, 'phase': 3, 'title': 'Day 30 - Graduation', 'focus': 'You are a different speaker than Day 1', 'drill': 'Record the same topic you used on Day 1. Listen to both. The gap between them is your growth. Own it.', 'tip': 'Influential speaking is not a destination. It is a daily practice. Begin again.', 'format': 'Positive Reflection'}]

